export default {"html":"<p data-line=\"0\" class=\"code-line\">Ionic 7 deprecated <code>swipeToClose</code>.</p>\n<blockquote data-line=\"2\" class=\"code-line\">\n<p data-line=\"2\" class=\"code-line\">Re: swipeToClose being deprecated -- The current thinking is that modals should only be swipeable when either using the card modal or the sheet modal. The fact that non-card/sheet modals could be swipeable was a mistake on our end. This change is being done to better align with native iOS and Android behavior.</p>\n</blockquote>\n<p data-line=\"4\" class=\"code-line\"><a href=\"https://github.com/ionic-team/ionic-framework/issues/25362#issuecomment-1139804151\" rel=\"noopener noreferrer\" target=\"_blank\">https://github.com/ionic-team/ionic-framework/issues/25362#issuecomment-1139804151</a><a href=\"https://github.com/ionic-team/ionic-framework/issues/25362#issuecomment-1139804151\" style=\"display:none\" target=\"_blank\" rel=\"noopener noreferrer\">https://github.com/ionic-team/ionic-framework/issues/25362#issuecomment-1139804151</a></p>\n<p data-line=\"6\" class=\"code-line\">To align with native iOS and Android behavior, modals other than card and sheet modals can no longer be dismissed with a swipe. That said, for some use cases—like a Twitter-style image viewer—swiping to close is more convenient for users, and it is a pattern many users already expect. So let us implement <code>swipeToClose</code> behavior ourselves. This is an Angular implementation.</p>\n<h2 id=\"alternative-implementation\" data-line=\"8\" class=\"code-line\"><a class=\"header-anchor-link\" href=\"#alternative-implementation\" aria-hidden=\"true\"></a> Alternative implementation</h2>\n<p data-line=\"10\" class=\"code-line\">Implement it on the page component used inside the Modal. The basic approach is to grab the page component itself with <code>ElementRef</code>, then listen for <code>touchstart</code> and <code>touchend</code> on that element. Compare the <code>clientY</code> values from <code>touchmove</code> when <code>touchstart</code> and <code>touchend</code> fire, and dismiss when <code>touchstart</code> is above <code>touchend</code>. The full implementation looks like this.</p>\n<div class=\"code-block-container\"><pre class=\"shiki github-dark\" style=\"background-color:#151e2c;color:#e1e4e8\"><code class=\"code-line\" data-line=\"12\"><span class=\"line\"><span style=\"color:#F97583\">import</span><span style=\"color:#E1E4E8\"> { Component, ElementRef, OnInit } </span><span style=\"color:#F97583\">from</span><span style=\"color:#9ECBFF\"> '@angular/core'</span><span style=\"color:#E1E4E8\">;</span></span>\n<span class=\"line\"><span style=\"color:#F97583\">import</span><span style=\"color:#E1E4E8\"> { IonicSlides, ModalController } </span><span style=\"color:#F97583\">from</span><span style=\"color:#9ECBFF\"> '@ionic/angular'</span><span style=\"color:#E1E4E8\">;</span></span>\n<span class=\"line\"><span style=\"color:#F97583\">import</span><span style=\"color:#E1E4E8\"> { fromEvent, zipWith, withLatestFrom } </span><span style=\"color:#F97583\">from</span><span style=\"color:#9ECBFF\"> 'rxjs'</span><span style=\"color:#E1E4E8\">;</span></span>\n<span class=\"line\"></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">@</span><span style=\"color:#B392F0\">Component</span><span style=\"color:#E1E4E8\">({</span><span style=\"color:#F97583\">...</span><span style=\"color:#E1E4E8\">})</span></span>\n<span class=\"line\"><span style=\"color:#F97583\">export</span><span style=\"color:#F97583\"> class</span><span style=\"color:#B392F0\"> ModalPage</span><span style=\"color:#F97583\"> implements</span><span style=\"color:#B392F0\"> OnInit</span><span style=\"color:#E1E4E8\"> {</span></span>\n<span class=\"line\"></span>\n<span class=\"line\"><span style=\"color:#F97583\">  constructor</span><span style=\"color:#E1E4E8\">(</span><span style=\"color:#F97583\">private</span><span style=\"color:#FFAB70\"> modalCtrl</span><span style=\"color:#F97583\">:</span><span style=\"color:#B392F0\"> ModalController</span><span style=\"color:#E1E4E8\">, </span><span style=\"color:#F97583\">private</span><span style=\"color:#FFAB70\"> elementRef</span><span style=\"color:#F97583\">:</span><span style=\"color:#B392F0\"> ElementRef</span><span style=\"color:#E1E4E8\">) {}</span></span>\n<span class=\"line\"></span>\n<span class=\"line\"><span style=\"color:#F97583\">  public</span><span style=\"color:#B392F0\"> ngOnInit</span><span style=\"color:#E1E4E8\">() {</span></span>\n<span class=\"line\"><span style=\"color:#F97583\">    const</span><span style=\"color:#79B8FF\"> watchSwipe$</span><span style=\"color:#F97583\"> =</span><span style=\"color:#B392F0\"> fromEvent</span><span style=\"color:#E1E4E8\">&lt;</span><span style=\"color:#B392F0\">TouchEvent</span><span style=\"color:#E1E4E8\">&gt;(</span><span style=\"color:#79B8FF\">this</span><span style=\"color:#E1E4E8\">.elementRef.nativeElement, </span><span style=\"color:#9ECBFF\">'touchstart'</span><span style=\"color:#E1E4E8\">)</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">      .</span><span style=\"color:#B392F0\">pipe</span><span style=\"color:#E1E4E8\">(</span></span>\n<span class=\"line\"><span style=\"color:#B392F0\">        zipWith</span><span style=\"color:#E1E4E8\">(</span></span>\n<span class=\"line\"><span style=\"color:#B392F0\">          fromEvent</span><span style=\"color:#E1E4E8\">&lt;</span><span style=\"color:#B392F0\">TouchEvent</span><span style=\"color:#E1E4E8\">&gt;(</span><span style=\"color:#79B8FF\">this</span><span style=\"color:#E1E4E8\">.elementRef.nativeElement, </span><span style=\"color:#9ECBFF\">'touchend'</span><span style=\"color:#E1E4E8\">).</span><span style=\"color:#B392F0\">pipe</span><span style=\"color:#E1E4E8\">(</span></span>\n<span class=\"line\"><span style=\"color:#B392F0\">            withLatestFrom</span><span style=\"color:#E1E4E8\">(</span><span style=\"color:#B392F0\">fromEvent</span><span style=\"color:#E1E4E8\">&lt;</span><span style=\"color:#B392F0\">TouchEvent</span><span style=\"color:#E1E4E8\">&gt;(</span><span style=\"color:#79B8FF\">this</span><span style=\"color:#E1E4E8\">.elementRef.nativeElement, </span><span style=\"color:#9ECBFF\">'touchmove'</span><span style=\"color:#E1E4E8\">)),</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">          ),</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">        ),</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">      )</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">      .</span><span style=\"color:#B392F0\">subscribe</span><span style=\"color:#E1E4E8\">(([</span><span style=\"color:#FFAB70\">touchstart</span><span style=\"color:#E1E4E8\">, [</span><span style=\"color:#FFAB70\">_</span><span style=\"color:#E1E4E8\">, </span><span style=\"color:#FFAB70\">touchmove</span><span style=\"color:#E1E4E8\">]]) </span><span style=\"color:#F97583\">=&gt;</span><span style=\"color:#E1E4E8\"> {</span></span>\n<span class=\"line\"><span style=\"color:#F97583\">        const</span><span style=\"color:#79B8FF\"> touchstartClientY</span><span style=\"color:#F97583\"> =</span><span style=\"color:#E1E4E8\"> touchstart.touches</span></span>\n<span class=\"line\"><span style=\"color:#F97583\">          ?</span><span style=\"color:#E1E4E8\"> touchstart.touches[</span><span style=\"color:#79B8FF\">0</span><span style=\"color:#E1E4E8\">].clientY</span></span>\n<span class=\"line\"><span style=\"color:#F97583\">          :</span><span style=\"color:#E1E4E8\"> touchstart.detail[</span><span style=\"color:#79B8FF\">1</span><span style=\"color:#E1E4E8\">].clientY;</span></span>\n<span class=\"line\"><span style=\"color:#F97583\">        const</span><span style=\"color:#79B8FF\"> touchmoveClientY</span><span style=\"color:#F97583\"> =</span><span style=\"color:#E1E4E8\"> touchmove.touches </span><span style=\"color:#F97583\">?</span><span style=\"color:#E1E4E8\"> touchmove.touches[</span><span style=\"color:#79B8FF\">0</span><span style=\"color:#E1E4E8\">].clientY </span><span style=\"color:#F97583\">:</span><span style=\"color:#E1E4E8\"> touchmove.detail[</span><span style=\"color:#79B8FF\">1</span><span style=\"color:#E1E4E8\">].clientY;</span></span>\n<span class=\"line\"><span style=\"color:#F97583\">        const</span><span style=\"color:#79B8FF\"> yDiff</span><span style=\"color:#F97583\"> =</span><span style=\"color:#E1E4E8\"> touchstartClientY </span><span style=\"color:#F97583\">-</span><span style=\"color:#E1E4E8\"> touchmoveClientY;</span></span>\n<span class=\"line\"></span>\n<span class=\"line\"><span style=\"color:#F97583\">        const</span><span style=\"color:#79B8FF\"> threshold</span><span style=\"color:#F97583\"> =</span><span style=\"color:#E1E4E8\"> touchmove.touches </span><span style=\"color:#F97583\">?</span><span style=\"color:#F97583\"> -</span><span style=\"color:#79B8FF\">50</span><span style=\"color:#F97583\"> :</span><span style=\"color:#F97583\"> -</span><span style=\"color:#79B8FF\">5</span><span style=\"color:#E1E4E8\">;</span></span>\n<span class=\"line\"></span>\n<span class=\"line\"><span style=\"color:#F97583\">        if</span><span style=\"color:#E1E4E8\"> (yDiff </span><span style=\"color:#F97583\">&lt;</span><span style=\"color:#E1E4E8\"> threshold </span><span style=\"color:#F97583\">&amp;&amp;</span><span style=\"color:#E1E4E8\"> touchstart.timeStamp </span><span style=\"color:#F97583\">&lt;=</span><span style=\"color:#E1E4E8\"> touchmove.timeStamp) {</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">          watchSwipe$.</span><span style=\"color:#B392F0\">unsubscribe</span><span style=\"color:#E1E4E8\">();</span></span>\n<span class=\"line\"><span style=\"color:#79B8FF\">          this</span><span style=\"color:#E1E4E8\">.modalCtrl.</span><span style=\"color:#B392F0\">dismiss</span><span style=\"color:#E1E4E8\">();</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">        }</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">      });</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">  }</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">}</span></span>\n<span class=\"line\"></span></code></pre></div><p data-line=\"49\" class=\"code-line\"><code>fromEvent</code> watches <code>touchstart</code> and <code>touchend</code>, and <code>zipWith</code> pairs them. I use <code>withLatestFrom</code> to combine <code>touchend</code> with <code>touchmove</code>. When <code>touchstart</code> and <code>touchend</code> are paired, I compare their <code>clientY</code> values and dismiss when <code>touchstart</code> is above <code>touchend</code>. Because <code>touchmove</code> fires between <code>touchstart</code> and <code>touchend</code>, I also compare their <code>timeStamp</code> values and dismiss the modal only when <code>touchstart</code> fired before <code>touchmove</code>.</p>\n<p data-line=\"51\" class=\"code-line\">Also, <code>touchmove.touches ? -50 : -5</code> adjusts the threshold because mouse and touch behave differently—when <code>touchmove</code> comes from the mouse, <code>clientY</code> grows larger. Tune the threshold smaller or larger if you want. This targets the whole Modal; if you only want <code>ion-header</code>, change what you listen on.</p>\n<h2 id=\"a-simpler-alternative\" data-line=\"53\" class=\"code-line\"><a class=\"header-anchor-link\" href=\"#a-simpler-alternative\" aria-hidden=\"true\"></a> A simpler alternative</h2>\n<p data-line=\"55\" class=\"code-line\">The code above keeps the Modal looking the same. If a sheet-like appearance is acceptable, you can get close to the same behavior by creating the modal like this. Pick the approach that fits your intent and use case.</p>\n<div class=\"code-block-container\"><pre class=\"shiki github-dark\" style=\"background-color:#151e2c;color:#e1e4e8\"><code class=\"code-line\" data-line=\"57\"><span class=\"line\"><span style=\"color:#79B8FF\">this</span><span style=\"color:#E1E4E8\">.modal </span><span style=\"color:#F97583\">=</span><span style=\"color:#F97583\"> await</span><span style=\"color:#79B8FF\"> this</span><span style=\"color:#E1E4E8\">.modalCtrl.</span><span style=\"color:#B392F0\">create</span><span style=\"color:#E1E4E8\">({</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">    backdropDismiss: </span><span style=\"color:#79B8FF\">true</span><span style=\"color:#E1E4E8\">,</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">    backdropBreakpoint: </span><span style=\"color:#79B8FF\">0</span><span style=\"color:#E1E4E8\">,</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">    breakpoints: [</span><span style=\"color:#79B8FF\">0</span><span style=\"color:#E1E4E8\">, </span><span style=\"color:#79B8FF\">1</span><span style=\"color:#E1E4E8\">],</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">    initialBreakpoint: </span><span style=\"color:#79B8FF\">1</span><span style=\"color:#E1E4E8\">,</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">    handle: </span><span style=\"color:#79B8FF\">false</span><span style=\"color:#E1E4E8\">,</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">    showBackdrop: </span><span style=\"color:#79B8FF\">true</span><span style=\"color:#E1E4E8\">,</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">    canDismiss: </span><span style=\"color:#79B8FF\">true</span><span style=\"color:#E1E4E8\">,</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">    component: MyModalComponent,</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">    mode: </span><span style=\"color:#9ECBFF\">'ios'</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">});</span></span>\n<span class=\"line\"></span></code></pre></div><h2 id=\"summary\" data-line=\"71\" class=\"code-line\"><a class=\"header-anchor-link\" href=\"#summary\" aria-hidden=\"true\"></a> Summary</h2>\n<p data-line=\"73\" class=\"code-line\">With RxJS, this stays simpler than an <code>addEventListener</code> implementation, does it not? See you next time.</p>\n","headings":[{"id":"alternative-implementation","text":"Alternative implementation","level":2},{"id":"a-simpler-alternative","text":"A simpler alternative","level":2},{"id":"summary","text":"Summary","level":2}]} as const;
